/// Enumeration for error codes returned by the diagnostics API.
///
/// Most diagnostics API functions may return some of these values to indicate specific errors.
///
/// **Since Tizen:**
/// - 6.0
/// @nodoc
abstract class diagnostics_error_e {
  /// < Successful
  static const int DIAGNOSTICS_ERROR_NONE = 0;

  /// < Invalid parameter
  static const int DIAGNOSTICS_ERROR_INVALID_PARAMETER = -22;

  /// < I/O error
  static const int DIAGNOSTICS_ERROR_IO_ERROR = -5;

  /// < Out of memory
  static const int DIAGNOSTICS_ERROR_OUT_OF_MEMORY = -12;

  /// < Device or resource busy
  static const int DIAGNOSTICS_ERROR_RESOURCE_BUSY = -16;

  /// < Time out
  static const int DIAGNOSTICS_ERROR_TIMED_OUT = -1073741823;

  /// < Not supported
  static const int DIAGNOSTICS_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Try again
  static const int DIAGNOSTICS_ERROR_TRY_AGAIN = -11;

  /// < Permission denied
  static const int DIAGNOSTICS_ERROR_PERMISSION_DENIED = -13;
}

